"""sklearn.multiclass — One-vs-Rest and One-vs-One multiclass strategies."""
import numpy as np
from sklearn.base import BaseEstimator, ClassifierMixin, clone


class OneVsRestClassifier(BaseEstimator, ClassifierMixin):
    """One-vs-the-rest (OvR) multiclass strategy.

    Parameters
    ----------
    estimator : classifier
    """

    def __init__(self, estimator=None):
        self.estimator = estimator

    def fit(self, X, y):
        X, y = np.asarray(X, dtype=float), np.asarray(y)
        self.classes_ = np.unique(y)
        self.estimators_ = []
        for c in self.classes_:
            est = clone(self.estimator)
            binary_y = (y == c).astype(int)
            est.fit(X, binary_y)
            self.estimators_.append(est)
        return self

    def predict(self, X):
        X = np.asarray(X, dtype=float)
        scores = np.column_stack([
            est.predict_proba(X)[:, 1] if hasattr(est, 'predict_proba')
            else est.predict(X).astype(float)
            for est in self.estimators_
        ])
        return self.classes_[np.argmax(scores, axis=1)]

    def predict_proba(self, X):
        X = np.asarray(X, dtype=float)
        probs = np.column_stack([
            est.predict_proba(X)[:, 1] if hasattr(est, 'predict_proba')
            else est.predict(X).astype(float)
            for est in self.estimators_
        ])
        sums = probs.sum(axis=1, keepdims=True)
        sums[sums == 0] = 1
        return probs / sums


class OneVsOneClassifier(BaseEstimator, ClassifierMixin):
    """One-vs-One multiclass strategy.

    Parameters
    ----------
    estimator : classifier
    """

    def __init__(self, estimator=None):
        self.estimator = estimator

    def fit(self, X, y):
        X, y = np.asarray(X, dtype=float), np.asarray(y)
        self.classes_ = np.unique(y)
        self.estimators_ = []
        self.pairs_ = []
        for i, ci in enumerate(self.classes_):
            for j, cj in enumerate(self.classes_):
                if i >= j:
                    continue
                mask = (y == ci) | (y == cj)
                est = clone(self.estimator)
                est.fit(X[mask], y[mask])
                self.estimators_.append(est)
                self.pairs_.append((ci, cj))
        return self

    def predict(self, X):
        X = np.asarray(X, dtype=float)
        n = X.shape[0]
        votes = np.zeros((n, len(self.classes_)))
        class_idx = {c: i for i, c in enumerate(self.classes_)}
        for est, (ci, cj) in zip(self.estimators_, self.pairs_):
            preds = est.predict(X)
            for k in range(n):
                votes[k, class_idx[preds[k]]] += 1
        return self.classes_[np.argmax(votes, axis=1)]


# ─── Stub base for upstream-only estimator classes ─────────────────


class _StubEstimator:
    """Permissive estimator base used by the auto-generated stubs.
    Records constructor kwargs; fit/transform/predict return sensible
    defaults (self, the input, or zeros) so calling code doesn't crash."""

    def __init__(self, *args, **kwargs):
        # Many real sklearn wrapper estimators (RFE, RFECV, OneVsRest,
        # CalibratedClassifierCV, …) take a base estimator as the first
        # positional arg. Accepting *args and stashing them on self._args
        # — plus exposing args[0] as ``self.estimator`` when there's just
        # one — keeps these stubs constructible without per-subclass code.
        self._args = args
        if len(args) == 1 and 'estimator' not in kwargs:
            self.estimator = args[0]
        for k, v in kwargs.items():
            setattr(self, k, v)

    def fit(self, X, y=None, **kwargs):
        try:
            import numpy as _np
            X = _np.asarray(X)
            self.n_features_in_ = X.shape[1] if X.ndim > 1 else 1
        except Exception:
            pass
        return self

    def fit_transform(self, X, y=None, **kwargs):
        self.fit(X, y, **kwargs)
        return self.transform(X)

    def transform(self, X):
        import numpy as _np
        return _np.asarray(X)

    def predict(self, X):
        import numpy as _np
        X = _np.asarray(X)
        return _np.zeros(len(X))

    def predict_proba(self, X):
        import numpy as _np
        X = _np.asarray(X)
        return _np.full((len(X), 2), 0.5)

    def score(self, X, y, **kwargs):
        return 0.0

    def get_params(self, deep=True):
        return {k: v for k, v in vars(self).items() if not k.startswith('_')}

    def set_params(self, **params):
        for k, v in params.items():
            setattr(self, k, v)
        return self



